def transform(grid):
    """Replace each isolated marker with the horizontal template pattern."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The template is the unique horizontal run of five non-background cells
    # (excluding single marker cells), conventionally on a row by itself.
    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    candidates = []
    for r, row in enumerate(g):
        runs = []
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            s = c
            while c < w and row[c] != bg:
                c += 1
            if c - s == 5:
                runs.append((s, row[s:c]))
        if runs:
            candidates.extend((r, s, vals) for s, vals in runs)
    if not candidates:
        return g
    # A full five-cell object is the template; remaining non-background
    # singleton objects mark the centers of copies.
    tr, ts, pattern = candidates[0]
    markers = [(r, c) for r in range(h) for c in range(w)
               if g[r][c] != bg and not (r == tr and ts <= c < ts + 5)]
    for r, c in markers:
        start = c - 2
        if 0 <= r < h and start >= 0 and start + 5 <= w:
            for j, value in enumerate(pattern):
                g[r][start + j] = value
    return g
